import{_ as t,o,c as n,a5 as s}from"./chunks/framework.Cooo9kuv.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"463-批量将指定图片或pdf插入合并到指定文件夹下所有pdf指定页面下","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["pdf页面插入图片","pdf页面插入指定pdf","合并pdf到指定页面","合并图片到pdf"]},"headers":[],"relativePath":"md/PDF批处理/463-批量将指定图片或pdf插入合并到指定文件夹下所有pdf指定页面下.md","filePath":"md/PDF批处理/463-批量将指定图片或pdf插入合并到指定文件夹下所有pdf指定页面下.md"}'),r={name:"md/PDF批处理/463-批量将指定图片或pdf插入合并到指定文件夹下所有pdf指定页面下.md"};function a(d,p,e,_,f,g){return o(),n("div",null,[...p[0]||(p[0]=[s('<p>批量在pdf指定页面插入指定图片或指定pdf页面，比如目标pdf页面原高度为210mm,插入一张图片后自动调整pdf页面高度，将图片插入到页面底部，并且在插入的图片下方预留一部分空间，避免因后续需要添加页脚被覆盖等问题。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250325111038174287223869871.png" alt=""></p><p><strong>支持在pdf页面中插入的文件格式：</strong>&#39;.png&#39;, &#39;.jpg&#39;, &#39;.jpeg&#39;, &#39;.bmp&#39;, &#39;.pdf&#39;</p><p>将图片或pdf文件批量插入到指定文件夹下所有pdf页面中下方，同页面插入图片或pdf，<strong>如下图所示：</strong></p><p><strong>图片为添加到页面后的效果，图片下方的空白区域为距离页面底部的百分比效果</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250325105907174287154761304.png" alt=""></p><p><strong>使用实例：</strong></p><p>A文件夹下有BCD等文件夹，同时有pdf文件，运行程序后，选择一张图片或一个pdf文件，选择A文件夹路径，百分比部分可以默认，</p><p>执行程序后，会自动在A文件夹下创建一个 <strong>已添加图片pdf存储_file</strong> 文件夹，将A文件夹下所有pdf文件批量处理后保存在该文件夹下，并且保存原来在A文件夹下的pdf所在文件夹结构。</p><p><strong>结构图对比</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251020214924176096816440598.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p></blockquote><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251020215020176096822089154.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1632.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1632.html</a></p>',17)])])}const m=t(r,[["render",a]]);export{l as __pageData,m as default};
